// Windowless test for fish_lsp.cpp -- the analysis half of mep's own
// Fish language server (`mep-fish-lsp`). Drives the pure functions
// directly: no process, no JSON-RPC client. CHECK(), never assert(): the
// Release build strips assert(). Generated by tools/new_language.py.
#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>

#include "fish_lsp.h"

namespace {
int g_checks = 0;

void Check(bool ok, const char *expr, int line) {
    g_checks++;
    if (ok) return;
    std::fprintf(stderr, "CHECK FAILED: %s at %s:%d\n", expr, __FILE__, line);
    std::abort();
}
#define CHECK(c) Check((c), #c, __LINE__)

std::vector<std::string> L(const std::string &text) {
    std::vector<std::string> out;
    std::string cur;
    for (char c : text) {
        if (c == '\n') {
            out.push_back(cur);
            cur.clear();
        } else {
            cur += c;
        }
    }
    out.push_back(cur);
    return out;
}

bool HasCode(const std::vector<FishLspDiagnostic> &ds, const char *code) {
    for (const auto &d : ds)
        if (d.code == code) return true;
    return false;
}

const char *kSample =
    "# greet things\n"                       // 0
    "set -g greeting hello\n"                // 1
    "function greet -a name -d 'Say hello'\n"  // 2
    "    set -l msg \"$greeting, $name\"\n"   // 3
    "    echo $msg (count $argv)\n"           // 4
    "end\n"                                  // 5
    "greet world\n"                          // 6
    "echo $greeting\n";                      // 7

void TestSyntaxErrors() {
    // fish's own first error, message and position.
    auto doc = FishLspAnalyze(L("if true\n    echo hi\n"));
    auto ds = FishLspDiagnostics(*doc);
    CHECK(ds.size() == 1 && ds[0].code == "syntax-error");
    CHECK(ds[0].message == "Missing end to balance this if statement");
    CHECK(ds[0].range.line == 0 && ds[0].range.col == 0 && ds[0].range.end_col == 2);

    doc = FishLspAnalyze(L("echo ${HOME}"));
    ds = FishLspDiagnostics(*doc);
    CHECK(ds.size() == 1 && ds[0].message == "Variables cannot be bracketed. In fish, please use {$HOME}.");
    CHECK(ds[0].range.col == 6);

    doc = FishLspAnalyze(L("echo $?"));
    CHECK(FishLspDiagnostics(*doc)[0].message == "$? is not the exit status. In fish, please use $status.");
    doc = FishLspAnalyze(L("a=b"));
    CHECK(FishLspDiagnostics(*doc)[0].message == "Unsupported use of '='. In fish, please use 'set a b'.");
    doc = FishLspAnalyze(L("break"));
    CHECK(FishLspDiagnostics(*doc)[0].message == "'break' while not inside of loop");
    doc = FishLspAnalyze(L("echo (echo 'x)"));
    CHECK(FishLspDiagnostics(*doc)[0].message == "Unexpected end of string, quotes are not balanced");
    doc = FishLspAnalyze(L("begin; end foo"));
    CHECK(FishLspDiagnostics(*doc)[0].message == "'end' does not take arguments. Did you forget a ';'?");
    doc = FishLspAnalyze(L("true | and false"));
    CHECK(FishLspDiagnostics(*doc)[0].message == "The 'and' command can not be used in a pipeline");
    doc = FishLspAnalyze(L("echo }"));
    CHECK(FishLspDiagnostics(*doc)[0].message == "Unexpected '}' for unopened brace");
    doc = FishLspAnalyze(L("{ echo a; } && { echo b }"));
    CHECK(FishLspDiagnostics(*doc).empty());
    doc = FishLspAnalyze(L(kSample));
    CHECK(FishLspDiagnostics(*doc).empty());

    // The --fish-check line matches `fish --no-execute`'s first stderr line.
    CHECK(FishLspFishCheck("echo ok\n", "f.fish").empty());
    CHECK(FishLspFishCheck("echo ok\nend\n", "f.fish") == "f.fish (line 2): 'end' outside of a block");
    CHECK(FishLspFishCheck("echo |", "f.fish") == "f.fish: Expected a command, but found end of the input");
}

void TestLints() {
    auto ds = FishLspDiagnostics(*FishLspAnalyze(L("function test\nend")));
    CHECK(HasCode(ds, "reserved-function-name"));
    ds = FishLspDiagnostics(*FishLspAnalyze(L("set -g status 1")));
    CHECK(HasCode(ds, "read-only-variable"));
    ds = FishLspDiagnostics(*FishLspAnalyze(L("string frob x\npath basename x\nstatus is-interactive")));
    CHECK(ds.size() == 1 && ds[0].code == "unknown-subcommand" && ds[0].range.line == 0);
    ds = FishLspDiagnostics(*FishLspAnalyze(L("[ -n foo\n[ -n foo ]")));
    CHECK(ds.size() == 1 && ds[0].code == "unclosed-test");
    ds = FishLspDiagnostics(*FishLspAnalyze(L("function f\n    return 1\n    echo no\nend")));
    CHECK(ds.size() == 1 && ds[0].code == "unreachable-code" && ds[0].unnecessary && ds[0].range.line == 2);
    // `or return` is conditional: nothing after it is flagged.
    ds = FishLspDiagnostics(*FishLspAnalyze(L("function f\n    true; or return\n    echo yes\nend")));
    CHECK(ds.empty());
}

void TestCompletion() {
    const auto doc = FishLspAnalyze(L(std::string(kSample) + "gre\necho $gr\nset -"));
    auto items = FishLspCompletions(*doc, 8, 3);
    bool greet = false;
    for (const auto &it : items) greet = greet || (it.label == "greet" && it.kind == FishLspKind::Function);
    CHECK(greet);
    items = FishLspCompletions(*doc, 9, 8);
    CHECK(!items.empty() && items[0].label == "greeting" && items[0].replace_start == 6);
    items = FishLspCompletions(*doc, 10, 5);
    bool local = false;
    for (const auto &it : items) local = local || it.label == "-l";
    CHECK(local);
    // Inside the function its locals are offered, outside they are not.
    items = FishLspCompletions(*FishLspAnalyze(L("function f -a xy\n    echo $x\nend\necho $x")), 1, 11);
    bool xy = false;
    for (const auto &it : items) xy = xy || it.label == "xy";
    CHECK(xy);
    items = FishLspCompletions(*FishLspAnalyze(L("function f -a xy\n    echo $x\nend\necho $x")), 3, 7);
    xy = false;
    for (const auto &it : items) xy = xy || it.label == "xy";
    CHECK(!xy);
}

void TestHoverAndSignature() {
    const auto doc = FishLspAnalyze(L(kSample));
    FishLspHoverInfo h = FishLspHover(*doc, 6, 2);
    CHECK(h.found && h.text.find("function greet name") != std::string::npos);
    CHECK(h.text.find("Say hello") != std::string::npos);
    h = FishLspHover(*doc, 4, 4);  // echo: a builtin
    CHECK(h.found && h.text.find("echo") != std::string::npos && h.text.find("builtin") != std::string::npos);
    h = FishLspHover(*doc, 7, 7);  // $greeting
    CHECK(h.found && h.text.find("line 2") != std::string::npos);
    FishLspSignatureHelp sh = FishLspSignatureAt(*doc, 6, 6);
    CHECK(sh.found && sh.label == "greet name" && sh.params.size() == 1 && sh.active_param == 0);
    const auto d2 = FishLspAnalyze(L("string replace "));
    sh = FishLspSignatureAt(*d2, 0, 15);
    CHECK(sh.found && sh.label.compare(0, 15, "string replace ") == 0);
}

void TestNavigation() {
    const auto doc = FishLspAnalyze(L(kSample));
    // $name -> the -a name
    auto defs = FishLspDefinition(*doc, 3, 31);
    CHECK(defs.size() == 1 && defs[0].range.line == 2);
    // $greeting (global) -> the set -g
    defs = FishLspDefinition(*doc, 3, 21);
    CHECK(defs.size() == 1 && defs[0].range.line == 1 && defs[0].range.col == 7);
    auto refs = FishLspReferences(*doc, 1, 9);
    CHECK(refs.size() == 3);
    // greet: the definition and the call
    refs = FishLspReferences(*doc, 6, 1);
    CHECK(refs.size() == 2);
    std::string err;
    auto edits = FishLspRename(*doc, 6, 1, "welcome", &err);
    CHECK(edits.size() == 2 && edits[0].new_text == "welcome");
    edits = FishLspRename(*doc, 3, 12, "text", &err);  // msg
    CHECK(edits.size() == 2);
    edits = FishLspRename(*doc, 3, 12, "bad name", &err);
    CHECK(edits.empty() && !err.empty());
    // A function-local and a global of the same name stay apart.
    const auto d2 = FishLspAnalyze(L("set -g x 1\nfunction f\n    set -l x 2\n    echo $x\nend\necho $x"));
    CHECK(FishLspReferences(*d2, 3, 11).size() == 2);
    CHECK(FishLspReferences(*d2, 5, 6).size() == 2);
    // argv cannot be renamed
    CHECK(!FishLspPrepareRename(*doc, 4, 25).found);
}

void TestOutlineAndFolds() {
    const auto doc = FishLspAnalyze(L(std::string(kSample) + "abbr -a gco git checkout\n"));
    const auto syms = FishLspSymbols(*doc);
    bool func = false, var = false, abbr = false;
    for (const auto &s : syms) {
        func = func || (s.name == "greet" && s.kind == FishLspSymbolKind::Function && s.detail == "Say hello");
        var = var || (s.name == "greeting" && s.kind == FishLspSymbolKind::Variable);
        abbr = abbr || s.name == "gco";
    }
    CHECK(func && var && abbr);
    const auto folds = FishLspFolds(*FishLspAnalyze(L("# a\n# b\nif true\n    echo\nelse\n    echo\nend")));
    bool block = false, comment = false;
    for (const auto &f : folds) {
        block = block || (f.start_line == 2 && f.end_line == 5);
        comment = comment || (f.start_line == 0 && f.end_line == 1 && f.kind == "comment");
    }
    CHECK(block && comment);
}

void TestFormat() {
    std::string err;
    auto edits = FishLspFormat(L("if true\necho  hi\nend"), 100, &err);
    CHECK(edits.size() == 1 && edits[0].new_text.find("    echo hi") != std::string::npos);
    edits = FishLspFormat(L("echo hi"), 100, &err);
    CHECK(edits.empty());
}

void TestRobustness() {
    // Every query on every prefix of a file must not crash.
    const std::string src = std::string(kSample) +
                            "switch $x\n    case 'a*' b\n        echo (string upper $x | string trim)\nend\n"
                            "for i in (seq 3); echo $i; end\nwhile read -l line; and test -n \"$line\"\n"
                            "    { echo $line } 2>/dev/null &\nend\nargparse h/help 'n/name=' -- $argv\n"
                            "echo $_flag_name \"$(date)\" 'x\\'y' \\\n    continued\n";
    for (size_t n = 0; n <= src.size(); n++) {
        const auto lines = L(src.substr(0, n));
        const auto doc = FishLspAnalyze(lines);
        const int last = static_cast<int>(lines.size()) - 1;
        const int col = static_cast<int>(lines.back().size());
        FishLspDiagnostics(*doc);
        FishLspCompletions(*doc, last, col);
        FishLspHover(*doc, last, col);
        FishLspSignatureAt(*doc, last, col);
        FishLspDefinition(*doc, last, col);
        FishLspReferences(*doc, last, col);
        FishLspSymbols(*doc);
        FishLspFolds(*doc);
        std::string err;
        FishLspFormat(lines, 100, &err);
    }
    // argparse flags resolve to their spec.
    const auto doc = FishLspAnalyze(L(src));
    const auto defs = FishLspDefinition(*doc, 17, 7);
    CHECK(defs.size() == 1 && defs[0].range.line == 16);
}

}  // namespace

int main() {
    TestSyntaxErrors();
    TestLints();
    TestCompletion();
    TestHoverAndSignature();
    TestNavigation();
    TestOutlineAndFolds();
    TestFormat();
    TestRobustness();
    std::printf("fish_lsp_test: %d checks passed\n", g_checks);
    return 0;
}
